import{c as i,a1 as l,U as s,j as n,g as t,o as a,a6 as c,p as u,n as d}from"./chunks/framework.h4W4t1IS.js";const x=JSON.parse(`{"title":"Amorçage de l'application","description":"","frontmatter":{"title":"Amorçage de l'application","status":"ready","tags":["architecture","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"architecture/amorcage.md","filePath":"architecture/amorcage.md"}`),p={name:"architecture/amorcage.md"},m={id:"frontmatter-title",tabindex:"-1"};function f(r,e,h,g,q,b){const o=l("Icon");return s(),n("div",null,[t("h1",m,[a(c(r.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1)),e[1]||(e[1]=a()),u(o,{icon:"mdi:bell-circle",style:{color:"var(--vp-c-tip-1)","vertical-align":"-0.1em","margin-left":"0.3em"},"aria-label":"Nouveau contenu"})]),e[2]||(e[2]=d('<p>L&#39;<strong>amorçage</strong> (<em>bootstrap</em>) est l&#39;étape où l&#39;application assemble ses objets avant de traiter la première action de l&#39;utilisateur. Il est concentré dans la méthode <code>main</code>.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Définir l&#39;amorçage d&#39;une application</li><li>Décrire les étapes de l&#39;amorçage d&#39;une application <a href="/420-w30-sf-po2/lexique.html#mvc" class="lexicon-link" title="Patron architectural en trois couches : le modèle (domaine, ignore tout du reste), la vue (affiche des DTOs, ignore le modèle), le contrôleur (orchestre les deux, connaît modèle ET vue).">MVC</a></li><li>Expliquer pourquoi tout le câblage doit vivre à un seul endroit</li></ul></div><h2 id="les-etapes-de-l-amorcage" tabindex="-1">Les étapes de l&#39;amorçage <a class="header-anchor" href="#les-etapes-de-l-amorcage" aria-label="Permalink to &quot;Les étapes de l&#39;amorçage&quot;">​</a></h2><ol><li><strong>Créer les services partagés</strong> : repositories, données initiales, etc.</li><li><strong>Créer le <a href="/420-w30-sf-po2/lexique.html#routeur" class="lexicon-link" title="Composante qui achemine chaque requête émise par une vue vers le contrôleur approprié, de sorte que la vue n&#39;a pas à connaître le contrôleur.">Routeur</a></strong> et lui faire connaître les contrôleurs de l&#39;application.</li><li><strong>Lancer la première requête</strong>, qui affiche le premier écran.</li></ol><h2 id="pourquoi-tout-cabler-au-meme-endroit" tabindex="-1">Pourquoi tout câbler au même endroit <a class="header-anchor" href="#pourquoi-tout-cabler-au-meme-endroit" aria-label="Permalink to &quot;Pourquoi tout câbler au même endroit&quot;">​</a></h2><ul><li>Les contrôleurs, les vues et les repositories ne créent jamais eux-mêmes leurs collaborateurs : ils les reçoivent (<a href="/420-w30-sf-po2/lexique.html#injection-de-dependances" class="lexicon-link" title="Technique consistant à fournir à une classe ses collaborateurs de l&#39;extérieur (par constructeur, par mutateur ou en paramètre de méthode) plutôt que de les créer elle-même.">injection de dépendances</a>).</li><li>Changer une implémentation (par exemple, remplacer un <a href="/420-w30-sf-po2/lexique.html#repository" class="lexicon-link" title="Patron de conception qui fournit une interface pour accéder aux données d&#39;une source de données, encapsulant la logique de persistance et permettant de séparer les préoccupations entre la couche de domaine et la couche d&#39;accès aux données.">repository</a> en mémoire) ne demande de modifier que l&#39;amorçage.</li><li>Lire <code>main</code> suffit pour savoir de quoi l&#39;application est composée.</li></ul><div class="tip custom-block"><p class="custom-block-title">Un seul endroit qui connaît tout</p><p>L&#39;amorçage est le seul endroit du programme qui connaît à la fois les <a href="/420-w30-sf-po2/lexique.html#abstraction" class="lexicon-link" title="Un des quatre piliers de la POO : se concentrer sur ce qu&#39;un objet fait plutôt que sur comment il le fait. Se réalise en Java par les classes abstraites et les interfaces.">abstractions</a> et toutes leurs implémentations concrètes. Plus il est proche du point d&#39;entrée (<code>main</code>), moins le reste du code dépend de classes concrètes.</p></div>',8))])}const _=i(p,[["render",f]]);export{x as __pageData,_ as default};
